expect_grep "/restore-drill ok$" "$FIX/pings"
expect_eq "$(ops '.drill | [.sampled, .matched]')" '[100,100]'

case_ "restore drill: the snapshot has no dump, or pg_restore fails: /fail dump_restore, teardown"
setup_db
rm "$FIX/db/rws.dump"
