setup_db
printf 'NL-1 2026-08 %s 10\n' "$(printf 'a%.0s' {1..32})" >"$FIX/sums-1"
printf 'NL-1 2026-08 %s 10\n' "$(printf 'c%.0s' {1..32})" >"$FIX/sums-2"
run rws-restore-drill --force
expect_rc 1
