expect_no_grep "never read" "$C/out"
: >"$FIX/pings"
touch -d '-6 minutes' "$RWS_SRV/owner/www/v1/meta.json"
run rws-tick
expect_grep "/owner-publisher/fail stale$" "$FIX/pings"
: >"$FIX/pings"
